function cleanRegionStr(v) {
  if (!v) return "";
  const s = String(v).trim();
  const l = s.toLowerCase();
  if (["null", "undefined", "none", "n/a", "na", "-", "—", "selected asian region", "all"].includes(l)) return "";
  return s;
}

const explicitKey = cleanRegionStr(router.region_key || body.region_key || context.key);
const explicitName = cleanRegionStr(router.region_name || body.region_name || context.name || context.city || context.country);
