  { key: "pakistan_peshawar", name: "Peshawar, Pakistan", city: "Peshawar", province: "Khyber Pakhtunkhwa", country: "Pakistan", subregion: "South Asia", lat: 34.0151, lon: 71.5249, tz: "PKT", offset: 5, temp: 33.0, hum: 52, vpd: 2.25, wind: 9.0, capacity: 610, surge: 16.0, thermal: 7.5, evap: 3.9, eff: 81 },
