  { key: "pakistan_gwadar", name: "Gwadar, Balochistan, Pakistan", city: "Gwadar", province: "Balochistan", country: "Pakistan", subregion: "South Asia", lat: 25.1216, lon: 62.3254, tz: "PKT", offset: 5, temp: 31.5, hum: 78, vpd: 1.10, wind: 22.0, capacity: 150, surge: 12.0, thermal: 6.1, evap: 2.9, eff: 85 },
  { key: "india_delhi", name: "Delhi, India", city: "Delhi", province: "Delhi", country: "India", subregion: "South Asia", lat: 28.6139, lon: 77.2090, tz: "IST", offset: 5.5, temp: 34.0, hum: 65, vpd: 1.85, wind: 7.0, capacity: 5500, surge: 19.5, thermal: 9.8, evap: 4.1, eff: 83 },
  { key: "india_mumbai", name: "Mumbai, India", city: "Mumbai", province: "Maharashtra", country: "India", subregion: "South Asia", lat: 19.0760, lon: 72.8777, tz: "IST", offset: 5.5, temp: 31.8, hum: 82, vpd: 0.95, wind: 15.0, capacity: 4200, surge: 14.0, thermal: 7.2, evap: 2.6, eff: 86 },
  { key: "bangladesh_dhaka", name: "Dhaka, Bangladesh", city: "Dhaka", province: "Dhaka", country: "Bangladesh", subregion: "South Asia", lat: 23.8103, lon: 90.4125, tz: "BST", offset: 6, temp: 32.0, hum: 80, vpd: 1.05, wind: 9.5, capacity: 2800, surge: 15.0, thermal: 7.5, evap: 2.8, eff: 85 },
  { key: "bangladesh_sylhet", name: "Sylhet, Bangladesh", city: "Sylhet", province: "Sylhet", country: "Bangladesh", subregion: "South Asia", lat: 24.8949, lon: 91.8687, tz: "BST", offset: 6, temp: 29.5, hum: 88, vpd: 0.70, wind: 6.0, capacity: 420, surge: 11.0, thermal: 5.5, evap: 2.1, eff: 89 },
  { key: "china_beijing", name: "Beijing, China", city: "Beijing", province: "Beijing", country: "China", subregion: "East Asia", lat: 39.9042, lon: 116.4074, tz: "CST", offset: 8, temp: 27.5, hum: 55, vpd: 1.65, wind: 12.0, capacity: 9500, surge: 13.5, thermal: 6.2, evap: 3.5, eff: 86 },
  { key: "china_shanghai", name: "Shanghai, China", city: "Shanghai", province: "Shanghai", country: "China", subregion: "East Asia", lat: 31.2304, lon: 121.4737, tz: "CST", offset: 8, temp: 29.0, hum: 75, vpd: 1.20, wind: 14.0, capacity: 8200, surge: 16.0, thermal: 7.8, evap: 3.0, eff: 84 },
