const j = $input.first().json || {};
function parse(value) { try { return typeof value === 'object' ? value : JSON.parse(value); } catch (e) { return {}; } }
let router = {};
try { router = $('Match Region').first().json || {}; } catch (e) {}
const state = parse(j.state_vector);
const m = state.metadata || {};
const p = state.physics_metrics || {};
const t = state.telemetry || {};
const l = state.ledger || {};
const riskState = state.calculated_risk_state || {};
const region = m.region || j.region || router.matched_region_name || '';
const intent = router.intent_type || j.intent_type || 'weather_summary_query';
const field = router.requested_field || j.requested_field || '';
const query = String(m.user_query || j.user_query || j.chatInput || j.original_message || router.user_message || '').toLowerCase();
const responseLanguage = String(j.response_language || router.response_language || m.response_language || 'en').toLowerCase().startsWith('ur') ? 'ur' : 'en';
const channel = router.channel || j.channel || 'chat';

function fmt(value, unit) {
  if (value === null || value === undefined || value === '') return 'Not available';
  const clean = typeof value === 'number' ? Math.round(value * 100) / 100 : value;
  return String(clean) + (unit || '');
}

const temperature = t.temperature_celsius ?? j.temperature_celsius;
const humidity = t.humidity_percentage ?? j.humidity_percentage;
const heatIndex = p.heat_index_celsius ?? j.heat_index_celsius;
const vpd = p.vapor_pressure_deficit_kpa ?? j.vapor_pressure_deficit_kpa;
const wind = t.wind_speed_kmh ?? j.wind_speed_kmh;
const gridSurge = p.grid_demand_surge_percent ?? j.grid_demand_surge_percent;
const thermal = p.thermal_overhead_percent ?? j.thermal_overhead_percent;
const evaporation = p.evaporation_loss_percent ?? j.evaporation_loss_percent;
const irrigation = l.water_irrigation_efficiency_pct ?? j.water_irrigation_efficiency_pct;
const capacity = l.grid_available_capacity_mw ?? j.grid_available_capacity_mw;
const risk = riskState.initial_risk_level ?? j.risk_level ?? 'MEDIUM';
const score = riskState.mission_criticality_score ?? j.mission_criticality_score ?? 65;

// GUARD: If region is missing, Null, or undefined
const isNullRegion = !region || ["null", "none", "undefined", "n/a", "selected asian region"].includes(String(region).toLowerCase().trim());
if (isNullRegion) {
  const noRegionEn = "Please select a region from the Asia map (or specify an Asian city or country like Karachi, Multan, Islamabad, Tokyo, etc.), and I will provide you with the live intelligence and details.";
  const noRegionUr = "براہ کرم ایشیا کے نقشے سے کوئی علاقہ منتخب کریں (یا کسی ایشیائی شہر یا ملک جیسے کراچی، ملتان، اسلام آباد، ٹوکیو کا نام بتائیں)، تاکہ میں آپ کو لائیو معلومات فراہم کر سکوں۔";
  const output = responseLanguage === 'ur' ? noRegionUr : noRegionEn;
  return [{ json: { ...j, output, chat_response: output, final_response: output, speech_en: noRegionEn, speech_ur: noRegionUr, channel } }];
}

let englishOutput = "";
let urduOutput = "";
const rLower = region.toLowerCase();

// Check if query is farmer/agriculture related
