  urduOutput = `**${region} میں بجلی کی متوقع اضافی طلب (Demand Surge)**\n\n• **طلب میں اضافہ:** **+${fmt(gridSurge, '%')}**\n• **بنیادی وجہ:** زیادہ درجہ حرارت (**${fmt(temperature, '°C')}**) اور ہیٹ انڈیکس (**${fmt(heatIndex, '°C')}**) کی وجہ سے کولنگ کا بڑھتا ہوا بوجھ۔\n• **ٹرانسمیشن اوورہیڈ:** **${fmt(thermal, '%')}**۔`;
}

// 14. Grid risk query
else if (intent === 'grid_risk_query' || query.includes('grid risk')) {
