  else if (query.includes('humidity') || query.includes('humid')) f = 'humidity';
  else if (query.includes('heat index') || query.includes('feels like')) f = 'heat_index';
  else if (query.includes('vpd') || query.includes('vapor pressure')) f = 'vpd';
  else if (query.includes('wind')) f = 'wind_speed';

  if (f === 'temperature') {
    englishOutput = `**Current Temperature in ${region}**\n\n• **Ambient Temperature:** **${fmt(temperature, '°C')}** (Feels like **${fmt(heatIndex, '°C')}** with heat index)\n• **Atmospheric Context:** Relative humidity is **${fmt(humidity, '%')}** with surface wind at **${fmt(wind, ' km/h')}**.\n• **Operational Advisory:** Moderate outdoor activity during peak daylight hours and ensure field personnel remain hydrated.`;
    urduOutput = `**${region} میں موجودہ درجہ حرارت**\n\n• **درجہ حرارت:** **${fmt(temperature, '°C')}** (ہیٹ انڈیکس کے ساتھ محسوس ہونے والا درجہ حرارت: **${fmt(heatIndex, '°C')}**)\n• **ہوا میں نمی:** **${fmt(humidity, '%')}** | ہوا کی رفتار: **${fmt(wind, ' km/h')}**\n• **ہدایت:** دوپہر کے اوقات میں براہِ راست دھوپ سے بچیں اور پانی کا زیادہ استعمال کریں۔`;
  } else if (f === 'humidity') {
