const j = $input.first().json || {};
const output = String(j.output || j.direct_response || 'I can help with WIaaS climate intelligence.');
return [{ json: { ...j, output, speech_en: j.speech_en || output, speech_ur: j.speech_ur || '', response_language: j.response_language || 'en' } }];

const input = $input.first().json || {};
let router = input;
try { router = $('Intent Router2').first().json || input; } catch (e) {}
const body = router.body && typeof router.body === 'object' ? router.body : {};
const context = router.region_context && typeof router.region_context === 'object'
  ? router.region_context
  : (body.region_context && typeof body.region_context === 'object' ? body.region_context : {});
const explicitKey = String(router.region_key || body.region_key || context.key || '').trim();
const explicitName = String(router.region_name || body.region_name || context.name || context.city || context.country || '').trim();

function normalizeEntries(value) {
  const source = value && value.regions !== undefined ? value.regions : value;
  const entries = [];
  if (Array.isArray(source)) {
    for (const item of source) {
      if (typeof item === 'string') entries.push({ key: item, name: item });
      else if (item && typeof item === 'object') {
        const key = item.key || item.region_key || item.id || '';
        const name = item.name || item.region_name || item.city || item.country || key;
        if (key || name) entries.push({ ...item, key: key || name, name });
      }
    }
  } else if (source && typeof source === 'object') {
    for (const [key, value] of Object.entries(source)) {
      if (['status', 'count', 'message'].includes(key)) continue;
      entries.push(value && typeof value === 'object'
        ? { ...value, key, name: value.name || value.region_name || value.city || key }
        : { key, name: String(value || key) });
    }
  }
  return entries;
}

const supplied = router.available_regions || body.available_regions || router.asia_regions || body.asia_regions || [];
const entries = normalizeEntries(supplied);
if (explicitKey || explicitName) {
  const exists = entries.some((item) => item.key === explicitKey || item.name === explicitName);
  if (!exists) entries.unshift({
    ...context,
    key: explicitKey || explicitName,
    name: explicitName || explicitKey,
    city: router.city || body.city || context.city || '',
    province: router.province || body.province || context.province || '',
    country: router.country || body.country || context.country || '',
    country_code: router.country_code || body.country_code || context.country_code || '',
    asian_subregion: router.asian_subregion || body.asian_subregion || context.asian_subregion || '',
    latitude: router.latitude ?? body.latitude ?? context.latitude ?? null,
    longitude: router.longitude ?? body.longitude ?? context.longitude ?? null,
    timezone: router.timezone || body.timezone || context.timezone || '',
  });
}

return [{ json: {
  status: 'success',
  scope: 'ASIA',
  count: entries.length,
  regions: entries,
  supported_countries: router.supported_countries || body.supported_countries || [],
  selected_context: context,
} }];

let router = {};
try { router = $('Intent Router2').first().json || {}; } catch (e) {}
const input = $input.first().json || {};
const available = Array.isArray(router.available_regions) ? router.available_regions : (Array.isArray(input.available_regions) ? input.available_regions : []);
const regionNames = [...new Set(available.map((item) => typeof item === 'string' ? item : (item && (item.name || item.region_name || item.city || item.country))).filter(Boolean))];
const countries = Array.isArray(router.supported_countries) ? router.supported_countries : (Array.isArray(input.supported_countries) ? input.supported_countries : []);
const names = countries.map((item) => typeof item === 'string' ? item : (item && (item.name || item.country))).filter(Boolean);
const detail = regionNames.length
  ? 'WIaaS currently has access to ' + regionNames.length + ' Asian regions:\n\n' + regionNames.map((name) => '- ' + name).join('\n')
  : names.length
    ? 'The Region panel currently covers ' + names.length + ' Asian countries: ' + names.join(', ') + '.'
  : 'WIaaS Asia uses the country and city selected in the Region panel and supports Asian locations supplied by the map search.';
const message = detail + '\n\nSelect a country or city, then ask for weather, risk level, agriculture, grid, logistics, research, or a full multi-agent report.';
const urduMessage = regionNames.length
  ? 'WIaaS کو اس وقت ' + regionNames.length + ' ایشیائی علاقوں تک رسائی حاصل ہے:\n\n' + regionNames.map((name) => '- ' + name).join('\n') + '\n\nکسی ملک یا شہر کو منتخب کریں، پھر موسم، خطرے، زراعت، بجلی، لاجسٹکس، تحقیق یا مکمل رپورٹ کے بارے میں پوچھیں۔'
  : 'ریجن پینل میں دستیاب کوئی بھی ایشیائی ملک یا شہر منتخب کریں، پھر اپنی مطلوبہ معلومات پوچھیں۔';
const responseLanguage = String(router.response_language || input.response_language || 'en').toLowerCase().startsWith('ur') ? 'ur' : 'en';
const output = responseLanguage === 'ur' ? urduMessage : message;
return [{ json: { output, direct_response: output, chat_response: output, final_response: output, speech_en: message, speech_ur: urduMessage, response_language: responseLanguage, channel: router.channel || 'webhook' } }];

const j = $input.first().json;
let raw = j.output || j.text || j.response || j.chatOutput || (j.message && j.message.content) || j.direct_response || "";
raw = String(raw).replace(/```[a-z]*|```/gi,"");
const bad = /(the user wants|constraints?|let'?s extract|i need to|i must|system prompt|workflow|internal|reasoning|agent prompt|as an ai)/i;
let clean = raw.split(/\n/).filter(x=>{const t=x.trim(); if(!t) return true; return !bad.test(t);}).join("\n").replace(/\n{3,}/g,"\n\n").trim();
if(!clean){ clean = "Hi! How can I help you with WIaaS today?"; }
return [{ json: { output: clean, direct_response: clean } }];

const input = $input.first().json;
const body = input.body ?? {};
function pick(){ for (const x of arguments) if (typeof x === "string" && x.trim() !== "") return x; return ""; }
const original = String(pick(input.chatInput, input.user_message, input.message, input.text, body.chatInput, body.user_message, body.message, body.text)).trim();
const text = " " + original.toLowerCase().replace(/[^a-z0-9_+%\s]/g, " ").replace(/\s+/g, " ").trim() + " ";
const hit = (kw) => text.indexOf(" " + kw + " ") !== -1;
const score = (list) => { const m = []; for (const k of list) if (hit(k)) m.push(k); return m; };

function cleanRegionStr(v) {
  if (!v) return "";
  const s = String(v).trim();
  const l = s.toLowerCase();
  if (["null", "undefined", "none", "n/a", "na", "-", "—", "selected asian region", "all"].includes(l)) return "";
  return s;
}

const selectedPayload = { ...input, ...body };
const ctx = selectedPayload.region_context && typeof selectedPayload.region_context === 'object' ? selectedPayload.region_context : {};
const rawKey = cleanRegionStr(selectedPayload.region_key || ctx.key);
const rawName = cleanRegionStr(selectedPayload.region_name || ctx.name || ctx.city || ctx.country);
const hasSelectedRegion = Boolean(rawKey || rawName);

const CITY_KEYWORDS = [
  "karachi", "lahore", "islamabad", "multan", "faisalabad", "rawalpindi", "peshawar", "quetta",
  "hyderabad", "sukkur", "gwadar", "gilgit", "skardu", "sialkot", "gujranwala",
  "delhi", "mumbai", "dhaka", "sylhet", "beijing", "shanghai", "tokyo", "seoul", "bangkok",
  "jakarta", "dubai", "riyadh", "doha", "singapore", "kabul", "tashkent", "tehran", "baghdad",
  "pakistan", "india", "bangladesh", "china", "japan", "saudi arabia", "uae"
];
const lowerMsg = original.toLowerCase();
const mentionsLocation = CITY_KEYWORDS.some(k => lowerMsg.includes(k));

const CRISIS      = ["anomaly","polygon","crisis","threat","osint","emergency","drought","heatwave","disaster","evacuation","hazard","triage"];
const FAQ_DEF     = ["what is wiaas","whats wiaas","how does it work","how does wiaas work","what can you do","what do you do","who are you","what are you","explain wiaas","how do i use"];
const MATH_VERBS  = ["calculate","compute","convert","formula","equation","solve"];
const WIAAS       = [
  "run analysis","run wiaas","wiaas analysis","wiaas","risk level","risk report","generate report","current status","current conditions",
  "irrigation","grid demand","agriculture impact","grid impact","logistics impact","research summary","heat stress","weather summary",
  "full report","full analysis","temperature","humidity","heat index","vpd","vapor pressure","crop stress","crop-stress","evaporation",
  "evaporation loss","grid capacity","available capacity","demand surge","heat sensitive","heat-sensitive","goods","cargo","electronic",
  "electronics","pharma","adaptation","adaptation laws","laws","regulations","policy","when should farmers","farmers irrigate",
  "flood","floods","agricultural impact","mitigation report","regional risk report","mitigation","report","farmer","farmers","crops",
  "better crops","better corps","corps build","crops build","crop issue","crop stress","scouting","raining","rain"
];
const WIAAS_REGEX = /\b(run|generate|give|show|create|produce|need|provide|have to)\b.{0,25}\b(report|analysis)\b|\b(farmer|farmers|crop|crops|corps|agriculture|rain|raining|waterlogging|temperature|humidity|heat index|feels like|crop stress|crop-stress|evaporation|grid capacity|demand surge|heat sensitive|heat-sensitive|cargo|adaptation|laws|regulations|policy|irrigate|irrigation|flood|floods|weather summary|full report|wiaas|current risk|risk level)\b/i;
const SENT        = ["rewrite","make professional","professional","make formal","formal","polite","rude","tone","sentiment","how does this sound","does this sound","proofread","reword"];
const FAQ_GREET   = ["hello","hi","hey","salam","assalam","help","good morning","good evening"];
const REGION_KEY = /\b[a-z]+_[a-z][a-z_]+\b/.test(text);

const asksRegionAccess = /(?:what|which|show|list|tell).{0,28}(?:regions?|locations?|cities|countries).{0,24}(?:access|support|cover|available)|(?:regions?|locations?).{0,24}(?:do you have|can you access|are supported)/i.test(original) || /(?:کن علاقوں|کون سے علاقوں|علاقوں تک رسائی|دستیاب علاقے|علاقوں کی فہرست)/.test(original);
const cr = score(CRISIS), fq = score(FAQ_DEF), mV = score(MATH_VERBS);
const wi = score(WIAAS), se = score(SENT), fg = score(FAQ_GREET);
const matchesWiaasRegex = WIAAS_REGEX.test(original);

let route, model, confidence, reason, needsFallback = false;
if (asksRegionAccess) { route = "wiaas_analysis_agent"; model = "existing-wiaas"; confidence = 0.99; reason = "Asian region access list"; }
else if ((hasSelectedRegion || mentionsLocation || wi.length > 0 || matchesWiaasRegex) && fq.length === 0 && mV.length === 0 && se.length === 0) {
  route = "wiaas_analysis_agent"; model = "existing-wiaas"; confidence = 0.98; reason = "WIaaS query / location context (" + (mentionsLocation ? "Location in prompt" : (hasSelectedRegion ? "Selected region" : "WIaaS pattern")) + ")";
}
else if (cr.length > 0 && wi.length === 0) { route = "crisis_triage_agent"; model = "minimax-m3"; confidence = 0.9; reason = "Crisis/anomaly (" + cr.slice(0,4).join(", ") + ")"; }
else if (fq.length > 0) { route = "faq_agent"; model = "minimax-m3"; confidence = 0.9; reason = "Definitional FAQ (" + fq.slice(0,2).join(", ") + ")"; }
else if (mV.length > 0) { route = "math_agent"; model = "deterministic"; confidence = 0.88; reason = "Calculation request (" + mV.slice(0,2).join(", ") + ")"; }
else if (wi.length > 0 || REGION_KEY) { route = "wiaas_analysis_agent"; model = "existing-wiaas"; confidence = 0.9; reason = "WIaaS keywords / pattern"; }
else if (se.length > 0) { route = "sentiment_agent"; model = "minimax-m3"; confidence = 0.85; reason = "Rewrite/tone (" + se.slice(0,3).join(", ") + ")"; }
else if (fg.length > 0) { route = "faq_agent"; model = "minimax-m3"; confidence = 0.8; reason = "Greeting/help (" + fg.slice(0,2).join(", ") + ")"; }
else { route = "fallback_classifier"; model = "minimax-m3"; confidence = 0.3; reason = "No confident regex match"; needsFallback = true; }

return [{ json: { ...input, route, confidence, reason, selected_model: model, needs_fallback_classifier: needsFallback, original_message: original } }];

const msg = String($input.first().json.original_message || "");
const t = msg.toLowerCase();
const nums = (msg.match(/-?\d+(?:\.\d+)?/g) || []).map(Number);
let output = "";
function round(x){ return Math.round(x * 100) / 100; }
if ((t.includes("heat index") || t.includes("feels like")) && nums.length >= 2) {
  const T = nums[0], R = nums[1];
  const Tf = T * 9/5 + 32;
  let hiF = -42.379 + 2.04901523*Tf + 10.14333127*R - 0.22475541*Tf*R - 0.00683783*Tf*Tf - 0.05481717*R*R + 0.00122874*Tf*Tf*R + 0.00085282*Tf*R*R - 0.00000199*Tf*Tf*R*R;
  const hiC = (hiF - 32) * 5/9;
  output = "Heat Index for " + T + "C at " + R + "% humidity = " + round(hiC) + "C (" + round(hiF) + "F).";
} else if (t.includes("vpd") || t.includes("vapor pressure")) {
  if (nums.length >= 2) {
    const T = nums[0], R = nums[1];
    const svp = 0.6108 * Math.exp((17.27 * T) / (T + 237.3));
    const vpd = svp * (1 - R/100);
    output = "VPD for " + T + "C at " + R + "% humidity = " + round(vpd) + " kPa.";
  } else { output = "To calculate VPD I need temperature (C) and relative humidity (%)."; }
} else if (t.includes("percent") || t.includes("percentage") || t.includes("%")) {
  if (nums.length >= 2) { output = round((nums[0] / nums[1]) * 100) + "% (" + nums[0] + " of " + nums[1] + ")."; }
  else { output = "To compute a percentage I need two numbers."; }
} else if (t.includes("mission criticality") || t.includes("criticality score")) {
  output = "Mission criticality is computed inside the WIaaS pipeline from heat index, VPD, grid surge, and thermal overhead. Ask for a WIaaS analysis of a region to get its score.";
} else if (nums.length >= 2 && /[+\-*x/]/.test(t)) {
  let r = nums[0];
  if (t.includes("+")) r = nums.reduce((a,b)=>a+b,0);
  else if (t.includes("-")) r = nums.reduce((a,b)=>a-b);
  else if (t.includes("x") || t.includes("*")) r = nums.reduce((a,b)=>a*b,1);
  else if (t.includes("/")) r = nums.reduce((a,b)=>a/b);
  output = "Result: " + round(r) + ".";
} else {
  output = "I can calculate heat index (temp + humidity), VPD, percentages, and basic arithmetic. Please include the numbers.";
}
return [{ json: { output, chat_response: output, final_response: output, route: "math_agent" } }];

const input = $input.first().json;
const body = input.body && typeof input.body === 'object' ? input.body : {};
const payload = { ...input, ...body };
const suppliedContext = payload.region_context && typeof payload.region_context === 'object' ? payload.region_context : {};

const channel = (input.headers !== undefined || input.body !== undefined) ? "webhook" : "chat";

function pickString(...candidates) {
  for (const candidate of candidates) {
    if (typeof candidate === "string" && candidate.trim() !== "") return candidate;
  }
  return "";
}

function cleanRegionStr(v) {
  if (!v) return "";
  const s = String(v).trim();
  const l = s.toLowerCase();
  if (["null", "undefined", "none", "n/a", "na", "-", "—", "selected asian region", "all"].includes(l)) return "";
  return s;
}

const message = pickString(
  input.chatInput,
  input.user_message,
  input.user_query,
  input.message,
  input.text,
  input.query,
  input.prompt,
  body.chatInput,
  body.user_message,
  body.user_query,
  body.message,
  body.text,
  body.query,
  body.prompt
);

const userMessage = String(message).trim();
const text = String(payload.routing_query || userMessage).toLowerCase();
const sessionId = pickString(input.sessionId, input.session_id, input.user_id, body.sessionId, body.session_id, body.user_id) || "anonymous";

// Asian catalog detection in prompt
const ASIAN_REGIONS = [
  { key: "pakistan_karachi", city: "Karachi", name: "Karachi, Pakistan" },
  { key: "pakistan_lahore", city: "Lahore", name: "Lahore, Pakistan" },
  { key: "pakistan_islamabad", city: "Islamabad", name: "Islamabad Capital Territory, Pakistan" },
  { key: "pakistan_multan", city: "Multan", name: "Multan, Punjab, Pakistan" },
  { key: "pakistan_faisalabad", city: "Faisalabad", name: "Faisalabad, Pakistan" },
  { key: "pakistan_rawalpindi", city: "Rawalpindi", name: "Rawalpindi, Pakistan" },
  { key: "pakistan_peshawar", city: "Peshawar", name: "Peshawar, Pakistan" },
  { key: "pakistan_quetta", city: "Quetta", name: "Quetta, Pakistan" },
  { key: "pakistan_hyderabad", city: "Hyderabad", name: "Hyderabad, Sindh, Pakistan" },
  { key: "pakistan_sukkur", city: "Sukkur", name: "Sukkur, Sindh, Pakistan" },
  { key: "pakistan_gwadar", city: "Gwadar", name: "Gwadar, Balochistan, Pakistan" },
  { key: "india_delhi", city: "Delhi", name: "Delhi, India" },
  { key: "india_mumbai", city: "Mumbai", name: "Mumbai, India" },
  { key: "bangladesh_dhaka", city: "Dhaka", name: "Dhaka, Bangladesh" },
  { key: "bangladesh_sylhet", city: "Sylhet", name: "Sylhet, Bangladesh" },
  { key: "china_beijing", city: "Beijing", name: "Beijing, China" },
  { key: "china_shanghai", city: "Shanghai", name: "Shanghai, China" },
  { key: "japan_tokyo", city: "Tokyo", name: "Tokyo, Japan" },
  { key: "saudi_riyadh", city: "Riyadh", name: "Riyadh, Saudi Arabia" },
  { key: "uae_dubai", city: "Dubai", name: "Dubai, United Arab Emirates" }
];

let extractedCity = "";
let extractedKey = "";
for (const item of ASIAN_REGIONS) {
  if (text.includes(item.city.toLowerCase())) {
    extractedCity = item.name;
    extractedKey = item.key;
    break;
  }
}

const rawName = cleanRegionStr(payload.region_name || suppliedContext.name || suppliedContext.city || suppliedContext.country);
const rawKey = cleanRegionStr(payload.region_key || suppliedContext.key);
const effectiveName = extractedCity || rawName;
const effectiveKey = extractedKey || rawKey;
const hasRegion = Boolean(effectiveName || effectiveKey);

const greetings = ["hi", "hello", "hey", "salam", "assalam", "good morning", "good afternoon", "good evening"];
const asksWhichRegions =
  text.includes("which region") || text.includes("what region") || text.includes("what regions") ||
  text.includes("which regions") || text.includes("list region") || text.includes("available region") ||
  text.includes("regions you support") || text.includes("supported region") || text.includes("which area") ||
  text.includes("what area") || /(?:کن علاقوں|کون سے علاقوں|علاقوں تک رسائی|دستیاب علاقے|علاقوں کی فہرست)/.test(userMessage);

const isGreeting = greetings.some(g => text === g || text.startsWith(g + " "));

function hasAny(words) {
  return words.some(w => text.includes(w));
}

// Intent classification
const requestedComprehensive = String(payload.request_kind || "").toLowerCase() === "comprehensive_report" || /\b(?:detailed|complete|full|comprehensive)\b[\s\S]{0,24}\b(?:all|everything|it)\b/.test(text);

const explicitFullReport = requestedComprehensive || hasAny([
  "run full analysis",
  "full analysis",
  "complete analysis",
  "generate complete",
  "complete report",
  "full report",
  "run wiaas analysis",
  "wiaas analysis",
  "run analysis",
  "generate report",
  "generate me a comprehensive",
  "generate me a report",
  "generate the report",
  "comprehensive report",
  "mitigation report",
  "regional risk report"
]);

let intentType = "weather_summary_query";
let field = "";

if (asksWhichRegions) {
  intentType = "faq_query";
} else if (explicitFullReport) {
  intentType = "full_report_query";
} else if (hasAny(["what can farmers do for better", "better crop", "better crops", "better corp", "better corps", "corps build", "crops build", "crop build"])) {
  intentType = "crop_building_query";
} else if (hasAny(["when should farmers be active", "active for crop", "active for any crop", "scouting window", "active hours"])) {
  intentType = "scouting_window_query";
} else if (hasAny(["what should farmers do", "what can farmers do", "farmers do in this weather", "priority action plan"])) {
  intentType = "farmer_action_query";
} else if (hasAny(["crop stress", "crop-stress", "crop issue"])) {
  intentType = "crop_stress_query";
} else if (hasAny(["when should farmers irrigate", "farmers irrigate", "recommend irrigation", "is irrigation recommended", "irrigate today"])) {
  intentType = "irrigation_query";
} else if (hasAny(["farmer", "farmers"])) {
  intentType = "farmer_query";
} else if (hasAny(["adaptation", "laws in", "adaptation laws", "climate act", "climate change act", "policy in", "regulations in"])) {
  intentType = "adaptation_query";
} else if (hasAny(["flood", "floods", "agricultural impact on the flood", "flood impact"])) {
  intentType = "flood_query";
} else if (hasAny(["heat sensitive", "heat-sensitive", "safe to transport", "safe to transfer", "cargo", "electronic", "electronics", "pharma", "transport goods"])) {
  intentType = "cargo_query";
} else if (hasAny(["when should farmers irrigate", "farmers irrigate", "recommend irrigation", "is irrigation recommended", "irrigate today"])) {
  intentType = "irrigation_query";
} else if (hasAny(["evaporation loss", "evaporation rate", "evaporation"])) {
  intentType = "evaporation_query";
} else if (hasAny(["grid capacity", "available capacity", "how much grid capacity"])) {
  intentType = "grid_capacity_query";
} else if (hasAny(["demand surge", "expected demand surge"])) {
  intentType = "demand_surge_query";
} else if (hasAny(["grid risk", "power risk", "blackout risk"])) {
  intentType = "grid_risk_query";
} else if (hasAny(["temperature", "temp", "how hot", "how cold"])) {
  intentType = "single_metric_query";
  field = "temperature";
} else if (hasAny(["humidity", "humid", "how high is the humidity"])) {
  intentType = "single_metric_query";
  field = "humidity";
} else if (hasAny(["heat index", "feels like"])) {
  intentType = "single_metric_query";
  field = "heat_index";
} else if (hasAny(["vpd", "vapor pressure"])) {
  intentType = "single_metric_query";
  field = "vpd";
} else if (hasAny(["wind speed", "wind"])) {
  intentType = "single_metric_query";
  field = "wind_speed";
} else if (hasAny(["risk level", "current risk", "mission criticality"])) {
  intentType = "risk_only_query";
} else if (hasAny(["agriculture", "agri"])) {
  intentType = "section_query";
  field = "agriculture";
} else if (hasAny(["grid", "power"])) {
  intentType = "section_query";
  field = "grid";
} else if (hasAny(["logistics", "supply", "transport"])) {
  intentType = "section_query";
  field = "logistics";
} else if (hasAny(["weather", "conditions", "summarize"])) {
  intentType = "weather_summary_query";
} else if (isGreeting) {
  intentType = "faq_query";
}

const analysisIntents = new Set([
  "single_metric_query",
  "weather_summary_query",
  "section_query",
  "risk_only_query",
  "full_report_query",
  "irrigation_query",
  "cargo_query",
  "adaptation_query",
  "flood_query",
  "crop_stress_query",
  "evaporation_query",
  "grid_capacity_query",
  "demand_surge_query",
  "grid_risk_query",
  "farmer_query",
  "farmer_action_query",
  "crop_building_query",
  "scouting_window_query"
]);

let directResponse = "";
if (asksWhichRegions) {
  directResponse = "WIaaS covers Asian territories across South, East, Central, and Western Asia. Tell me any city or country (e.g. Karachi, Islamabad, Multan, Tokyo, Beijing, Delhi, Riyadh) and I will provide you with live environmental intelligence.";
} else if (isGreeting) {
  directResponse = "Hi! I am the WIaaS Weather Intelligence assistant. Tell me an Asian region or ask about temperature, heat index, humidity, crop stress, irrigation timing, power grid risk, logistics safety, or request a full WIaaS analysis.";
}

// Guard: If it's an analysis intent but NO region is selected or found in query
let wiaasMode = asksWhichRegions ? "region_list" : (analysisIntents.has(intentType) ? "analysis" : "faq");
let regionStatus = hasRegion ? "resolved" : "missing";

if (analysisIntents.has(intentType) && !hasRegion) {
  regionStatus = "missing";
  directResponse = "Please select a region from the Asia map (or specify an Asian city or country like Karachi, Multan, Islamabad, Tokyo, etc.), and I will provide you with the live intelligence and details.";
}

return [
  {
    json: {
      ...payload,
      user_message: userMessage,
      channel,
      session_id: sessionId,
      intent_type: intentType,
      requested_field: field,
      region_key: effectiveKey,
      region_name: effectiveName,
      region_context: suppliedContext,
      wiaas_mode: wiaasMode,
      region_status: regionStatus,
      wiaas_focus: field || intentType,
      requested_region: effectiveName || userMessage,
      direct_response: directResponse
    }
  }
];
